window.SlopI18n && window.SlopI18n.add('tr', {
'ui.appdesc.photoslop': 'Katmanlar, maskeler, filtreler ve fırçalarla fotoğrafları masaüstü bir resim düzenleyicisi gibi düzenleyin. PSD dosyalarını açar ve kaydeder.',
'ui.appdesc.vector': 'Kalem araçları, şekiller ve boolean yollarla logolar, simgeler ve çizimler çizin; SVG, PDF ya da AI olarak dışa aktarın.',
'ui.appdesc.pdf': 'PDF dosyalarını düzenleyin, imzalayın ve dönüştürün. Birleştirin, bölün, sayfaları yeniden sıralayın, sayfa numaraları ve filigranlar ekleyin, formları doldurun.',
'ui.appdesc.label': 'Barkod ve etiket sayfaları tasarlayın, bir CSV ya da e-tablodan veri birleştirin ve termal yazıcılar için ZPL dışa aktarın.',
'ui.appdesc.cutout': 'Tek bir fotoğraftan ya da yüzlerce fotoğraftan, cihazınızda YZ ile arka planı kaldırın; ardından saydam, beyaz, bulanık ya da bir renk yapın.',
'ui.appdesc.aitools': 'Cihaz üzerinde yardımcılar: resimlerden ve taramalardan metin okuma, konuşmayı metne çevirme, fotoğraf gürültüsünü temizleme ve fotoğrafları etiketleme.',
'ui.appdesc.ocr': 'Fotoğraflardan ve taranmış PDF’lerden cihazınızda metin okuyun; ardından kopyalayın, .txt olarak kaydedin ya da aranabilir bir PDF yapın.',
'ui.appdesc.scan': 'Turn photos of pages into one clean PDF: the edges are found, the pages made flat and shadows removed, in colour or black and white, with searchable text.',   // English until translated (Slop Scan)
'ui.appdesc.html2pdf': 'Bir HTML dosyasını her sayfada üstbilgi, tarih ve QR kodla PDF’ye yazdırın. Hiçbir şey karşıya yüklenmez.',
'ui.appdesc.clean': 'Bir fotoğrafın sizin hakkınızda neleri ortaya koyduğunu görün (GPS, kamera, seri numarası ve tarih) ve bu alanları yeniden kodlamadan silin.',
'ui.appdesc.ai': 'WebGPU üzerinden, bilgisayarınızda çalışan bir YZ modeliyle çevrimdışı sohbet edin; önce sistem denetimi yapılır.',
'ui.appdesc.docs': 'Gerçek sayfalar, üstbilgiler ve altbilgilerle mektuplar, raporlar ve sözleşmeler yazın. Word dosyalarını açar ve kaydeder; sayfayla eşleşen bir PDF dışa aktarır.',
'ui.appdesc.tables': 'E-tablolarla çalışın: 300’den fazla işlev, grafikler ve pivot tablolar. Excel, ODS ve CSV dosyalarını açar; Excel ve CSV olarak kaydeder.',
'ui.appdesc.slides': 'Temalar, düzenler, geçişler ve animasyonlarla sunumlar hazırlayın. PowerPoint dosyalarını açar ve dışa aktarır, PDF dışa aktarır ve sunucu görünümüne sahiptir.',
'ui.appdesc.press': 'Ana sayfalar, zincirlenmiş metin ve baskıya hazır PDF dışa aktarımıyla dergiler, broşürler ve baskı sayfaları tasarlayın.',
'ui.appdesc.remix': 'Klipleri ve fotoğrafları bırakın, rastgele bir düzenleme alın, ardından SlopCut’ta ince ayar yapın.',
'ui.appdesc.slopedit': 'Çok parçalı bir zaman çizelgesinde, kırpmalar, geçişler ve başlıklarla video düzenleyin. Görüntüleriniz cihazınızdan hiçbir zaman çıkmaz.',
'ui.appdesc.resize': 'Resimleri ve videoları piksel boyutuna, yüzdeye ya da dosya boyutu sınırına göre yeniden boyutlandırın; sosyal medya ve e-posta ön ayarlarıyla.',
'ui.appdesc.upscale': 'Resimleri ve kısa videoları 2x ya da 4x büyütün; cihazınızda çalışan YZ büyütmeyle.',
'ui.appdesc.reports': 'Kişiler, Faturalar, Giderler ve CRM üzerinde salt okunur raporlar: aya göre kâr, kategoriye göre giderler, ödenmemiş faturalar ve takipler.',
'ui.appdesc.contacts': 'Bir adres defteri: vCard ve CSV içe aktarın, yinelenenleri bulup birleştirin, telefonlar ve posta uygulamaları için dışa aktarın.',
'ui.appdesc.inventory': 'Ürünleri ve stoğu konuma göre izleyin, barkodları kamerayla ya da USB tarayıcıyla okutun ve yeniden sipariş uyarıları alın.',
'ui.appdesc.orders': 'Müşteri siparişlerini taslaktan yerine getirmeye kadar alın; vergi ve indirimlerle. Bir siparişi faturaya dönüştürün.',
'ui.appdesc.quotes': 'Vergi ve geçerlilik tarihiyle teklifler ve tahminler yazın, gönderilenleri ve kabul edilenleri izleyin; evet denileni siparişe ya da faturaya çevirin.',
'ui.appdesc.purchases': 'Tedarikçilerden satın alma siparişleriyle stok sipariş edin, teslimatları envantere alın ve tedarikçi faturasını gider olarak kaydedin.',
'ui.appdesc.timesheets': 'Müşteri ve proje bazında bir zamanlayıcıyla ya da elle zaman takip edin, saatleri toplayın ve taslak bir faturaya yansıtın.',
'ui.appdesc.expenses': 'Fişleri ve faturaları tedarikçi ve kategoriye göre kaydedin; geri alınacak vergiyle birlikte deftere işleyin ve CSV dışa aktarın.',
'ui.appdesc.invoices': 'Boşluksuz numaralarla fatura düzenleyin, ödemeleri kaydedin, vadesi geçen bakiyeleri izleyin ve PDF yazdırın ya da dışa aktarın.',
'ui.appdesc.notes': 'Etiketler, sabitlemeler ve canlı önizlemeyle defterler ve Markdown notları tutun; Slop Drive’a kaydedilir.',
'ui.appdesc.paste': 'Metni, kodu ya da bir resmi süresi dolan bir bağlantı olarak paylaşın; altı dil için sözdizimi vurgulamasıyla.',
'ui.appdesc.effects': 'Katmanları anahtar kareler, yumuşatma ve parıltı, bozulma ve tane gibi efektlerle canlandırın; ardından video ya da PNG dizileri dışa aktarın.',
'ui.appdesc.img3d': 'Tek bir resmi, görüntüleyebileceğiniz ve OBJ ya da GLB olarak dışa aktarabileceğiniz bir 3B modele dönüştürün; cihazınızda.',
'ui.appdesc.sheetview': 'E-tabloları bu cihazda açın ve göz atın: sütunları sıralayın ve filtreleyin, gördüğünüzü dışa aktarın.',
'ui.appdesc.hex': 'Bir hex düzenleyici: her dosyayı bayt olarak görüntüleyin ve değiştirin; bulma, ofsetler ve büyük dosyalar için sayfalama.',
'ui.appdesc.eml': 'E-posta dosyalarını (.eml) önizleyin, yazdırın ya da PDF olarak kaydedin. Uzak resimler engellenir.',
'ui.appdesc.checksum': 'Bu cihazdaki herhangi bir dosya için SHA-256, SHA-1, SHA-384 ya da SHA-512 karmaları hesaplayın ve bir dosyayı yayımlanmış bir karmayla denetleyin.',
'ui.appdesc.diff': 'İki metni, kod dosyasını, JSON, CSV, PDF ya da resmi karşılaştırın; her değişikliği kelime kelime görün, sonra bir rapor ya da .patch indirin.',
'ui.appdesc.nodes': 'Bir düğüm hesap makinesi: her düğüm bir ad ve bir formüldür; başka bir formülde kullanılan ad bir bağlantıdır ve bir değişiklik altındaki tüm düğümleri günceller. Birimler, para birimi ve tarihler Slopculator’daki gibi.',
'ui.appdesc.signature': 'Adınız, unvanınız, şirketiniz, iletişim bilgileriniz, logonuz ve sosyal bağlantılarınızla bir e-posta imzası oluşturun, ardından Gmail, Outlook ya da Apple Mail’e kopyalayın.',
'ui.appdesc.transcribe': 'Bir ses kaydını, bir MP3’ü ya da bir videonun sesini bu cihazda metne çevirin; ardından metin, Word ya da altyazı olarak kaydedin.',
'ui.appdesc.recorder': 'Ekranınızı, bir pencereyi ya da sekmeyi, web kameranızı ya da mikrofonunuzu, ya da köşesinde web kamerası olan ekranı kaydedin. Kırpın ve WebM, MP4 ya da GIF olarak kaydedin.',
'ui.appdesc.sorter': 'Bir yığın fotoğrafı tek tek kaydırın: her birini beğenin, beğenmeyin ya da etiketleyin; ardından en iyilerini ZIP olarak ya da Slop Drive’da tutun.',
'ui.appdesc.serials': 'Bir fotoğraf grubundan benzersiz seri numaralarını sayın: benzersiz seri numaraları tablosu, toplamlar tablosu ve bir CSV dışa aktarımı; hepsi bu cihazda.',
'ui.appdesc.qr': 'Bağlantılar, Wi-Fi, kişiler, etkinlikler ve daha fazlası için QR kodları üretin; renkli olarak, SVG ya da PNG biçiminde ya da toplu olarak.',
'ui.appdesc.colors': 'Bir resimden renk seçin, ana renklerini bulun, paletler ve uyumlar oluşturun, WCAG kontrastını denetleyin ve HEX, RGB, HSL, OKLCH ve CMYK arasında dönüştürün.',
'ui.appdesc.fontcreator': 'Tarayıcıda kendi yazı tipinizi yapın: kalem ve şekillerle glifler çizin, yazdırılabilir bir sayfadan el yazınızı izleyin, bir TTF, OTF, WOFF ya da WOFF2 düzenleyin, harf aralıklarını ayarlayın ve TTF, OTF, WOFF2 ve CSS olarak dışa aktarın.',
'ui.appdesc.workflows': 'Uygulamaları tek bir toplu iş akışında zincirleyin: arka planları kaldırın, filigran ekleyin, yeniden boyutlandırın, dönüştürün, sıkıştırın ve çok sayıda dosyayı aynı anda zipleyin.',
'ui.appdesc.convert': 'Resimleri, PDF’leri, CSV, JSON, Markdown ve Base64’ü toplu olarak, cihazınızda dönüştürün.',
'ui.appdesc.calculator': 'Kâğıt bandı, birimler, para birimleri, tarih ve saatlerle ve kayıtlı hesaplamalarla bir hesap makinesi.',
'ui.appdesc.time': 'Dünya saati, toplantı planlayıcı ve saat dilimi dönüştürücü; kronometre ve zamanlayıcıyla birlikte.',
'ui.appdesc.crm': 'Müşterileri ve potansiyel müşterileri bir hat panosunda yönetin; tarihli notlar, takipler ve siparişlere bağlantılarla.',
'ui.appdesc.calendar': 'Ay, hafta ve ajanda görünümleriyle, tekrarlamalar, saat dilimleri ve .ics içe aktarımıyla günleri ve haftaları planlayın.',
'ui.appdesc.todo': 'Son tarihler, etiketler ve alt görevlerle görevleri ve listeleri tutun. Görevler Takvim’de görünür.',
'ui.appdesc.projects': 'Bir Kanban panosu ve Gantt zaman çizelgesiyle bir projeyi planlayın; bağımlılıklar, kontrol listeleri, kişiler ve CSV dışa aktarımıyla.',
'ui.appdesc.reminders': 'Takvim ve Yapılacaklar’daki her hatırlatıcı için tek bir zaman çizelgesi; erteleme ve tarayıcı bildirimleriyle.',
'ui.appdesc.ledger': 'Hesap planı, yevmiye, mizan ve yabancı para birimiyle çift taraflı defter.',
'ui.appdesc.admin': 'Şirket profilinizi, numaralandırmanızı ve para biriminizi ayarlayın; doğrulanmış yedekler ya da geri yüklemeler yapın.',
'ui.appdesc.drive': 'Tüm uygulamaların dosyaları için tek bir yerel sürücü: klasörler, arama, yinelenenler ve tek dosyalık yedek.',
'ui.appdesc.code': 'Slop Drive dosyalarınız için bir kod düzenleyici: sözdizimi vurgulama, arama ve korumalı bir HTML önizlemesi.',
'ui.appdesc.gallery': 'Fotoğraf kitaplığınıza zaman çizelgesi ve albümlere göre göz atın, fotoğrafları sıralayın ve birebir yinelenenleri bulun.',
'ui.appdesc.3d': 'İlkel şekiller, malzemeler ve ışıklarla basit 3B modeller ve sahneler kurun; PNG resimleri oluşturun.',
'ui.appdesc.music': 'Slop Drive’ınızdaki sesleri çalın; çalma listeleri, dalga formuyla arama, karıştırma ve tekrar ile.',
'ui.appdesc.authenticator': 'Herhangi bir metin yapıştırın ve gerçek bir slop mu yoksa ucuz bir insan taklidi mi olduğunu öğrenin.',
'ui.appdesc.watermark': 'Çok sayıda resmi logonuz ya da metninizle aynı anda filigranlayın, sonra hepsini bir ZIP olarak indirin. Hiçbir şey karşıya yüklenmez.',
'ui.appdesc.paint_classic': '1998 deneyimi: her MS Paint aracı, ona benzeyen bir pencerede.',
'ui.theme.not_listed': 'Bu tema listede yok.',
'ui.theme.no_storage': 'Kaydedilemedi: tarayıcı depolaması engellenmiş.',
});
